fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    assert_eq!(x1.len(), x2.len(), "input vectors must have the same length");

    let mut out = Vec::with_capacity(x1.len());
    for i in 0..x1.len() {
        let a = x1[i];
        let b = x2[i];
        let r = a & b;

        // Per-index properties (checked at runtime):
        debug_assert_eq!(r, a & b);          // equals bitwise AND
        debug_assert_eq!(a & b, b & a);      // commutative
        debug_assert_eq!(a & 0u8, 0u8);      // AND with zero yields zero
        debug_assert_eq!(a & a, a);          // idempotent
        debug_assert!(r <= a && r <= b);     // result <= each input

        out.push(r);
    }
    out
}